  const L = di.L || M.stats.avgCycle, ph = di.phase, ov = C.ovulationDay(L, M.stats.avgPeriod), warm = warmWindow({ phase: ph, cd: di.cd, L });
  const P = patterns(), notes = [], cards = [];
