      if (r.sunAm && t.rise) { const at = new Date(t.rise.getTime() + 20 * 6e4); if (at > now) list.push({ id: 7100 + i * 2, title: SUN_REM.am[0], body: SUN_REM.am[1], schedule: { at } }); }
