  const Y = t => (t >= D.rise && t <= D.set ? hy - 40 * Math.sin(Math.PI * (t - D.rise) / (D.set - D.rise)) : hy + 12 * Math.sin(Math.PI * ((t > D.set ? t - D.set : t + 24 - D.set) / N)));
