      lbl.textContent = d === cd ? `Today · day ${d}` : `Day ${d}`; lbl.setAttribute('text-anchor', d < L * .2 ? 'start' : d > L * .8 ? 'end' : 'middle');
      read.innerHTML = guideRead(d, L, P, ov, cd);
