  const go = () => { const sh = wsOpen(sfSheet(o), 'ws-herb ws-sf'); el.classList.remove('lift'); if (sh) { el.classList.add('out'); sh._onClose = () => el.classList.remove('out'); } };
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return go();
